<div id="kt_content_container" class="container-xxl py-5"><div class="d-flex flex-wrap flex-stack mb-7"><div><h1 class="fw-bold text-gray-900 mb-2">Datos Personales</h1><div class="text-muted fs-6">Administra la información de tu cuenta</div></div></div><div id="alerta-datos"></div><div class="card card-flush"><div class="card-body p-9"><form id="form_datos_personales"><div class="row g-6"><div class="col-md-6"><label class="required form-label">Nombre</label><input type="text" name="nombre" id="datos_nombre" class="form-control" required /></div><div class="col-md-6"><label class="required form-label">Correo electrónico</label><input type="email" name="email" id="datos_email" class="form-control" required /></div><div class="col-12"><label class="required form-label">Domicilio de entrega</label><textarea name="domicilio" id="datos_domicilio" class="form-control" rows="3" required></textarea><div class="text-muted fs-7 mt-2">Registra tu domicilio antes de confirmar un pedido.</div></div><div class="col-12"><div class="separator my-5"></div><h3 class="fw-bold mb-5">Cambiar contraseña</h3><label class="form-label">Nueva contraseña</label><input type="password" name="password" class="form-control" minlength="6" placeholder="Déjala vacía para conservar la actual" /></div><div class="col-12"><button type="submit" id="guardar_datos" class="btn btn-primary">Guardar cambios</button></div></div></form><div class="separator my-10"></div><div class="d-flex flex-wrap justify-content-between align-items-center"><div><h3 class="text-danger fw-bold mb-2">Desactivar cuenta</h3><p class="text-muted mb-0">Tu cuenta dejará de estar disponible para iniciar sesión.</p></div><button type="button" id="desactivar_cuenta" class="btn btn-light-danger">Desactivar mi cuenta</button></div></div></div></div>
<script>
(function () { const formulario = document.getElementById('form_datos_personales'), alerta = document.getElementById('alerta-datos'); fetch('actions/04.read_usuario_by_id.php').then(r => r.json()).then(respuesta => { if (!respuesta.success) { alerta.innerHTML = '<div class="alert alert-danger">' + respuesta.error + '</div>'; return; } const usuario = Array.isArray(respuesta.data) ? respuesta.data[0] : respuesta.data; document.getElementById('datos_nombre').value = usuario.nombre || ''; document.getElementById('datos_email').value = usuario.email || ''; document.getElementById('datos_domicilio').value = usuario.domicilio || ''; }); formulario.addEventListener('submit', function (evento) { evento.preventDefault(); fetch('actions/06.update_usuario.php', { method: 'POST', body: new FormData(formulario) }).then(r => r.json()).then(respuesta => { alerta.innerHTML = '<div class="alert alert-' + (respuesta.success ? 'success' : 'danger') + '">' + (respuesta.message || respuesta.error) + '</div>'; }); }); document.getElementById('desactivar_cuenta').addEventListener('click', function () { if (!confirm('¿Deseas desactivar tu cuenta? Esta acción cerrará tu sesión.')) return; fetch('actions/07.delete_usuario.php', { method: 'POST' }).then(r => r.json()).then(respuesta => { if (respuesta.success) window.location.href = 'login.php'; else alerta.innerHTML = '<div class="alert alert-danger">' + respuesta.error + '</div>'; }); }); })();
</script>
